use misterdiagram_sheet::{Context, Error, Value, formula};
struct Host;
impl Context for Host {
    fn resolve(&mut self, name: &str) -> Value {
        match name {
            "Width" => Value::Number(2.),
            "Height" => Value::Number(0.7),
            _ => Value::Error(Error::Ref),
        }
    }
    fn unit(&self, name: &str) -> Option<String> {
        matches!(name, "Width" | "Height").then(|| "IN".into())
    }
}
